body.script:
var TOKEN = document.body.getAttribute('data-token') || '';
var site = null, services = [], tickets = [];
var installEvt = null, apptSvc = null, proofTicket = null;
var LS = window.localStorage;
function h(s){ return (s==null?'':String(s)).replace(/[&<>"]/g, function(c){
    return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }
function toast(m){ var t=document.getElementById('toast'); t.textContent=m;
    t.classList.add('show'); setTimeout(function(){ t.classList.remove('show'); }, 3200); }
function tok(){ return LS.getItem('q_token') || ''; }
function setSession(token, email, name){ LS.setItem('q_token', token);
    LS.setItem('q_email', email||''); LS.setItem('q_name', name||''); }
function clearSession(){ LS.removeItem('q_token'); LS.removeItem('q_email'); LS.removeItem('q_name'); }

async function api(path, params){
    var r = await fetch('/api/queue/'+path, { method:'POST', credentials:'same-origin',
        headers:{'Content-Type':'application/json'},
        body: JSON.stringify({jsonrpc:'2.0', method:'call', id:1, params: params||{}}) });
    var j = await r.json();
    if (j.error) throw new Error((j.error.data && j.error.data.message) || j.error.message || 'Erreur');
    return j.result || {};
}

function renderNoSite(){
    document.getElementById('app').innerHTML =
        '<div class="card"><h2>Prendre un ticket</h2>'
        + '<p class="muted mt">Scannez le QR affiché à l\'entrée du site, ou saisissez son code :</p>'
        + '<div class="row mt"><input id="codeIn" placeholder="Code du site"/>'
        + '<button class="btn" id="goBtn">Ouvrir</button></div></div>';
    document.getElementById('goBtn').onclick = function(){
        var c = (document.getElementById('codeIn').value||'').trim();
        if (c) location.href = '/queue/u/' + encodeURIComponent(c);
    };
}

function loginCard(){
    var email = LS.getItem('q_email') || '';
    return '<div class="card"><h2>Se connecter</h2>'
        + '<p class="muted mt">Un code vous est envoyé par email pour prendre et suivre vos tickets.</p>'
        + '<div class="mt"><input id="emailIn" type="email" placeholder="Votre email" value="'+h(email)+'"/></div>'
        + '<button class="btn" id="sendBtn" style="margin-top:.6rem">Recevoir un code</button>'
        + '<div id="otpBox" style="display:none">'
        + '<div class="mt"><input id="otpIn" inputmode="numeric" placeholder="Code reçu"/></div>'
        + '<button class="btn" id="verifyBtn" style="margin-top:.6rem">Valider</button></div></div>';
}
function wireLogin(){
    var sendBtn = document.getElementById('sendBtn');
    if (sendBtn) sendBtn.onclick = async function(){
        var email = (document.getElementById('emailIn').value||'').trim();
        if (!email) return toast('Saisissez votre email');
        sendBtn.disabled = true;
        try { var res = await api('auth/request_otp', {email: email});
            if (res.status === 'error') toast(res.message);
            else { LS.setItem('q_email', email);
                document.getElementById('otpBox').style.display = 'block';
                toast(res.message || 'Code envoyé'); }
        } catch(e){ toast(e.message); } finally { sendBtn.disabled = false; }
    };
    var vBtn = document.getElementById('verifyBtn');
    if (vBtn) vBtn.onclick = async function(){
        var email = (document.getElementById('emailIn').value||'').trim();
        var otp = (document.getElementById('otpIn').value||'').trim();
        vBtn.disabled = true;
        try { var res = await api('auth/verify_otp', {email: email, otp: otp});
            if (res.status === 'error') toast(res.message);
            else { setSession(res.auth_token, res.customer.email, res.customer.name);
                toast('Bienvenue'); await loadTickets(); render(); }
        } catch(e){ toast(e.message); } finally { vBtn.disabled = false; }
    };
}

// ---- Actions ----
async function takeTicket(serviceId, remote){
    if (!tok()) { toast('Connectez-vous d\'abord'); return; }
    try { var res = await api('ticket/create',
            {auth_token: tok(), service_id: serviceId, qr_token: TOKEN, remote: !!remote});
        if (res.status === 'error') { if (res.code === 'auth_required') { clearSession(); render(); }
            toast(res.message); return; }
        toast(res.message || 'Ticket pris ✓');
        await loadTickets(); await loadSite(); render();
    } catch(e){ toast(e.message); }
}
async function cancelTicket(id){
    try { var res = await api('ticket/cancel', {auth_token: tok(), ticket_id: id});
        if (res.status === 'error') { toast(res.message); return; }
        await loadTickets(); await loadSite(); render();
    } catch(e){ toast(e.message); }
}
async function checkin(id){
    try { var res = await api('ticket/checkin', {auth_token: tok(), ticket_id: id});
        if (res.status === 'error') { toast(res.message); return; }
        toast('Enregistré ✓'); await loadTickets(); renderTicketsInto();
    } catch(e){ toast(e.message); }
}
async function pay(id, method, extra){
    var params = {auth_token: tok(), ticket_id: id, method: method};
    if (extra) for (var k in extra) params[k] = extra[k];
    try { var res = await api('ticket/pay', params);
        if (res.status === 'error') { toast(res.message); return; }
        if (res.payment_url) { window.open(res.payment_url, '_blank');
            toast('Réglez sur Wave — un agent validera'); }
        else { toast('Paiement déclaré'); }
        await loadTickets(); renderTicketsInto();
    } catch(e){ toast(e.message); }
}
function payProof(id){ proofTicket = id;
    var pi = document.getElementById('proofInput'); pi.value=''; pi.click(); }
async function logout(){
    try { await api('auth/logout', {auth_token: tok()}); } catch(e){}
    clearSession(); tickets = []; render();
}

// ---- Rendez-vous ----
function fmtDate(d){ var m=('0'+(d.getMonth()+1)).slice(-2), day=('0'+d.getDate()).slice(-2);
    return d.getFullYear()+'-'+m+'-'+day; }
function openAppt(id, name){
    apptSvc = id;
    document.getElementById('apptTitle').textContent = 'Rendez-vous — ' + name;
    var di = document.getElementById('apptDate');
    var today = new Date(); var max = new Date(); max.setDate(max.getDate()+14);
    di.min = fmtDate(today); di.max = fmtDate(max); di.value = fmtDate(today);
    document.getElementById('apptModal').style.display = 'flex';
    loadSlots();
}
function closeAppt(){ document.getElementById('apptModal').style.display='none'; apptSvc=null; }
async function loadSlots(){
    var box = document.getElementById('apptSlots');
    if (!tok()) { box.innerHTML = '<p class="muted">Connectez-vous pour réserver.</p>'; return; }
    var date = document.getElementById('apptDate').value;
    box.innerHTML = '<p class="muted">Chargement…</p>';
    try { var res = await api('slots', {service_id: apptSvc, date: date});
        if (res.status === 'error') { box.innerHTML = '<p class="muted">'+h(res.message)+'</p>'; return; }
        var slots = res.slots || [];
        box.innerHTML = slots.length
            ? slots.map(function(s){ return '<button class="btn '+(s.available?'':'ghost')+'"'
                + (s.available?'':' disabled')+' data-slot="'+h(s.time)+'">'+h(s.label)+'</button>'; }).join('')
            : '<p class="muted">Aucun créneau ce jour.</p>';
    } catch(e){ box.innerHTML = '<p class="muted">'+h(e.message)+'</p>'; }
}
async function book(slot){
    try { var res = await api('appointment/book', {auth_token: tok(), service_id: apptSvc, slot: slot});
        if (res.status === 'error') { toast(res.message); return; }
        toast('Rendez-vous réservé ✓'); closeAppt();
        await loadTickets(); await loadSite(); render();
    } catch(e){ toast(e.message); }
}

// ---- Chargement ----
async function loadSite(){
    if (!TOKEN) return;
    try { var res = await api('site', {qr_token: TOKEN});
        if (res.status === 'ok') { site = res.site; services = res.services || []; } else { site = false; }
    } catch(e){}
}
async function loadTickets(){
    if (!tok()) { tickets = []; return; }
    try { var res = await api('tickets', {auth_token: tok()});
        if (res.status === 'ok') tickets = res.tickets || [];
        else if (res.code === 'auth_required') { clearSession(); tickets = []; }
    } catch(e){}
}

// ---- Rendu ----
var ST = {waiting:['En attente','wait'], called:['À vous ! Présentez-vous','called'],
          serving:['En cours','serving'], scheduled:['Programmé','sched']};
function ticketHtml(t){
    var st = ST[t.state] || [t.state,'wait'];
    var pos = (t.state==='waiting' && t.position) ? ('Position '+t.position) : '';
    var eta = (t.eta_minutes && t.state==='waiting') ? ('~'+t.eta_minutes+' min') : '';
    var meta = [pos,eta].filter(Boolean).join(' · ');
    var sched = (t.state==='scheduled' && t.scheduled_time) ? ('Rendez-vous : '+h(t.scheduled_time)) : '';
    var pay = '';
    if (t.payment_state === 'pending') {
        pay = '<div class="paybox"><div class="paylbl">À régler : '+h(t.payment_amount)+' '+h(t.currency)+'</div>'
            + '<div class="row wrap">'
            + '<button class="btn" data-pay="wave" data-t="'+t.id+'">Payer avec Wave</button>'
            + '<button class="btn ghost" data-pay="proof" data-t="'+t.id+'">Preuve de paiement</button>'
            + '<button class="btn ghost" data-pay="counter" data-t="'+t.id+'">Payer au guichet</button></div></div>';
    } else if (t.payment_state === 'to_validate') {
        pay = '<div class="paybox"><div class="paylbl">Paiement déclaré — en attente de validation au guichet.</div></div>';
    } else if (t.payment_state === 'paid') {
        pay = '<div class="paybox paid">Payé ✓</div>';
    }
    var actions = '';
    if (t.state === 'scheduled') actions += '<button class="btn" data-checkin="'+t.id+'">Je suis arrivé(e)</button>';
    if (['waiting','called','scheduled'].indexOf(t.state) >= 0)
        actions += '<button class="btn red" data-cancel="'+t.id+'">Annuler</button>';
    return '<div class="ticket"><div class="num">'+h(t.name || '—')+'</div>'
        + '<div class="svcn">'+h(t.service)+'</div>'
        + '<span class="st '+st[1]+'">'+h(st[0])+'</span>'
        + (meta ? '<div class="info">'+h(meta)+'</div>' : '')
        + (sched ? '<div class="info">'+h(sched)+'</div>' : '')
        + pay
        + (actions ? '<div class="mt row wrap">'+actions+'</div>' : '')+'</div>';
}
function serviceHtml(s){
    var badges = '';
    if (s.appointment) badges += '<span class="badge">Rendez-vous</span>';
    if (s.payment_required) badges += '<span class="badge pay">'+h(s.price)+' '+h(s.currency)+'</span>';
    var remoteChk = s.remote
        ? '<label class="chk"><input type="checkbox" data-remote="'+s.id+'"/> Je ne suis pas sur place</label>' : '';
    var apptBtn = s.appointment
        ? '<button class="btn ghost" data-appt="'+s.id+'" data-name="'+h(s.name)+'">Rendez-vous</button>' : '';
    return '<div class="svc"><div><div class="n">'+h(s.name)+badges+'</div>'
        + '<div class="m">'+h(s.waiting)+' en attente</div>'+remoteChk+'</div>'
        + '<div class="row wrap" style="justify-content:flex-end">'
        + '<button class="btn" data-take="'+s.id+'">Ticket</button>'+apptBtn+'</div></div>';
}
function renderTicketsInto(){
    var el = document.getElementById('tickets');
    if (!el) return;
    var active = tickets.filter(function(t){
        return ['scheduled','waiting','called','serving'].indexOf(t.state) >= 0; });
    el.innerHTML = active.length ? ('<h2>Mes tickets</h2>' + active.map(ticketHtml).join('')) : '';
}
function render(){
    if (site) { document.getElementById('siteName').textContent = site.name;
        document.getElementById('siteCity').textContent = site.city || ''; }
    var logged = !!tok();
    document.getElementById('who').textContent = logged ? (LS.getItem('q_email')||'') : '';
    document.getElementById('logoutBtn').style.display = logged ? '' : 'none';

    var app = document.getElementById('app');
    if (!TOKEN) { renderNoSite(); return; }
    if (site === false) { app.innerHTML = '<div class="center muted">Site introuvable. Vérifiez le QR ou le code.</div>'; return; }
    if (!site) { app.innerHTML = '<div class="center muted">Chargement…</div>'; return; }

    var html = '<div class="install"><span>Vous êtes sur le portail web — rien à installer. '
        + 'Vous pouvez aussi <a href="/queue/app">installer l\'application</a>.</span>'
        + '<button class="btn ghost" id="installBtn" style="display:none">Installer</button></div>';
    html += '<div id="tickets"></div>';
    if (!logged) html += loginCard();
    html += '<h2>Services</h2><div class="card">'
        + (services.length ? services.map(serviceHtml).join('') : '<div class="muted">Aucun service disponible.</div>')
        + '</div>';
    app.innerHTML = html;
    renderTicketsInto();
    wireLogin();
    var ib = document.getElementById('installBtn');
    if (ib && installEvt) { ib.style.display = ''; ib.onclick = function(){ installEvt.prompt(); }; }
}

// ---- Événements ----
document.body.addEventListener('click', function(ev){
    var t = ev.target.closest('[data-take]');
    if (t) { var sid = parseInt(t.getAttribute('data-take'),10);
        var chk = document.querySelector('[data-remote="'+sid+'"]');
        takeTicket(sid, chk && chk.checked); return; }
    var a = ev.target.closest('[data-appt]');
    if (a) { openAppt(parseInt(a.getAttribute('data-appt'),10), a.getAttribute('data-name')); return; }
    var sl = ev.target.closest('[data-slot]');
    if (sl) { book(sl.getAttribute('data-slot')); return; }
    var c = ev.target.closest('[data-cancel]');
    if (c) { cancelTicket(parseInt(c.getAttribute('data-cancel'),10)); return; }
    var ci = ev.target.closest('[data-checkin]');
    if (ci) { checkin(parseInt(ci.getAttribute('data-checkin'),10)); return; }
    var p = ev.target.closest('[data-pay]');
    if (p) { var tid = parseInt(p.getAttribute('data-t'),10); var m = p.getAttribute('data-pay');
        if (m === 'proof') payProof(tid); else pay(tid, m); return; }
    if (ev.target.id === 'apptClose') { closeAppt(); return; }
    if (ev.target.id === 'apptModal') { closeAppt(); return; }
});
document.body.addEventListener('change', function(ev){
    if (ev.target.id === 'apptDate') loadSlots();
});
document.getElementById('proofInput').addEventListener('change', function(){
    var f = this.files[0]; if (!f || !proofTicket) return;
    var reader = new FileReader();
    reader.onload = function(){ var b64 = String(reader.result).split(',')[1] || '';
        pay(proofTicket, 'proof', {proof: b64, proof_filename: f.name}); };
    reader.readAsDataURL(f);
});
document.getElementById('logoutBtn').onclick = logout;

// PWA
window.addEventListener('beforeinstallprompt', function(e){ e.preventDefault(); installEvt = e;
    var ib = document.getElementById('installBtn'); if (ib){ ib.style.display=''; ib.onclick=function(){ e.prompt(); }; } });
if (TOKEN && 'serviceWorker' in navigator) {
    navigator.serviceWorker.register('/queue/sw.js', {scope:'/queue/u/'}).catch(function(){});
}

// démarrage + sondage (seuls les tickets se rafraîchissent, pour ne pas
// effacer une saisie en cours — code OTP, créneau, paiement).
async function tick(){ await loadTickets(); renderTicketsInto(); }
(async function(){ await loadSite(); await loadTickets(); render(); })();
setInterval(tick, 5000);
